head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil35605";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.month

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil35605.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    noticeIframe.location.href = "/helper/" + (String(((dma_pageContext.get("month") ?? "")) === null ? '' : ((dma_pageContext.get("month") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("month") ?? "")) === null ? '' : ((dma_pageContext.get("month") ?? "")))) + ".htm";
    $c.util.getComponent("m" + (String(((dma_pageContext.get("month") ?? "")) === null ? '' : ((dma_pageContext.get("month") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("month") ?? "")) === null ? '' : ((dma_pageContext.get("month") ?? ""))))).src = "/img/main/pop_month_" + (String(((dma_pageContext.get("month") ?? "")) === null ? '' : ((dma_pageContext.get("month") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("month") ?? "")) === null ? '' : ((dma_pageContext.get("month") ?? "")))) + "_selected.gif";
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setPeriod
 * @description set Period 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.setPeriod = function (str) {
    scwin.clearBtnImage();
    if (str === '01') {
        noticeIframe.location.href = "/helper/01.htm";
        $c.util.getComponent("m01").src = "/img/main/pop_month_01_selected.gif";
    } else {
        if (str === '02') {
            noticeIframe.location.href = "/helper/02.htm";
            $c.util.getComponent("m02").src = "/img/main/pop_month_02_selected.gif";
        } else {
            if (str === '03') {
                noticeIframe.location.href = "/helper/03.htm";
                $c.util.getComponent("m03").src = "/img/main/pop_month_03_selected.gif";
            } else {
                if (str === '04') {
                    noticeIframe.location.href = "/helper/04.htm";
                    $c.util.getComponent("m04").src = "/img/main/pop_month_04_selected.gif";
                } else {
                    if (str === '05') {
                        noticeIframe.location.href = "/helper/05.htm";
                        $c.util.getComponent("m05").src = "/img/main/pop_month_05_selected.gif";
                    } else {
                        if (str === '06') {
                            noticeIframe.location.href = "/helper/06.htm";
                            $c.util.getComponent("m06").src = "/img/main/pop_month_06_selected.gif";
                        } else {
                            if (str === '07') {
                                noticeIframe.location.href = "/helper/07.htm";
                                $c.util.getComponent("m07").src = "/img/main/pop_month_07_selected.gif";
                            } else {
                                if (str === '08') {
                                    noticeIframe.location.href = "/helper/08.htm";
                                    $c.util.getComponent("m08").src = "/img/main/pop_month_08_selected.gif";
                                } else {
                                    if (str === '09') {
                                        noticeIframe.location.href = "/helper/09.htm";
                                        $c.util.getComponent("m09").src = "/img/main/pop_month_09_selected.gif";
                                    } else {
                                        if (str === '10') {
                                            noticeIframe.location.href = "/helper/10.htm";
                                            $c.util.getComponent("m10").src = "/img/main/pop_month_10_selected.gif";
                                        } else {
                                            if (str === '11') {
                                                noticeIframe.location.href = "/helper/11.htm";
                                                $c.util.getComponent("m11").src = "/img/main/pop_month_11_selected.gif";
                                            } else {
                                                if (str === '12') {
                                                    noticeIframe.location.href = "/helper/12.htm";
                                                    $c.util.getComponent("m12").src = "/img/main/pop_month_12_selected.gif";
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
};

/**
 * @method
 * @name clearBtnImage
 * @description clear Btn Image 처리
 * @returns {void}
 * @hidden N
 */
scwin.clearBtnImage = function () {
    $c.util.getComponent("m01").src = "/img/main/pop_month_01.gif";
    $c.util.getComponent("m02").src = "/img/main/pop_month_02.gif";
    $c.util.getComponent("m03").src = "/img/main/pop_month_03.gif";
    $c.util.getComponent("m04").src = "/img/main/pop_month_04.gif";
    $c.util.getComponent("m05").src = "/img/main/pop_month_05.gif";
    $c.util.getComponent("m06").src = "/img/main/pop_month_06.gif";
    $c.util.getComponent("m07").src = "/img/main/pop_month_07.gif";
    $c.util.getComponent("m08").src = "/img/main/pop_month_08.gif";
    $c.util.getComponent("m09").src = "/img/main/pop_month_09.gif";
    $c.util.getComponent("m10").src = "/img/main/pop_month_10.gif";
    $c.util.getComponent("m11").src = "/img/main/pop_month_11.gif";
    $c.util.getComponent("m12").src = "/img/main/pop_month_12.gif";
};
